1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
usb: gadget: f_ncm: validate minimum block_len in
 ncm_unwrap_ntb()

The block_len read from the host-supplied NTB header is checked against
ntb_max but has no lower bound. When block_len is smaller than
opts->ndp_size, the bounds check of:
	ndp_index > (block_len - opts->ndp_size)
will underflow producing a huge unsigned value that ndp_index can never
exceed, defeating the check entirely.

The same underflow occurs in the datagram index checks against block_len
- opts->dpe_size.  With those checks neutered, a malicious USB host can
choose ndp_index and datagram offsets that point past the actual
transfer, and the skb_put_data() copies adjacent kernel memory into the
network skb.

Fix this by rejecting block lengths that cannot hold at least the NTB
header plus one NDP.  This will make block_len - opts->ndp_size and
block_len - opts->dpe_size both well-defined.

Commit 8d2b1a1ec9f5 ("CDC-NCM: avoid overflow in sanity checking") fixed
a related class of issues on the host side of NCM.

Fixes: 2b74b0a04d3e ("USB: gadget: f_ncm: add bounds checks to ncm_unwrap_ntb()")
Cc: stable <stable@kernel.org>
Assisted-by: gregkh_clanker_t1000
Link: https://patch.msgid.link/2026040753-baffle-handheld-624d@gregkh
Signed-off-by: Greg Kroah-Hartman <gregkh@linuxfoundation.org>

Here is the root cause:
The block_len field from the NTB header lacked a minimum bound check, allowing values smaller than the NDP size. This caused arithmetic underflow in subsequent bounds checks (e.g., ndp_index > (block_len - opts->ndp_size)), turning them into no-ops. A malicious USB host could then supply crafted ndp_index and datagram offsets to read kernel memory beyond the actual transfer buffer into the network packet via skb_put_data().

Here is the patch:

 static int ncm_unwrap_ntb(struct gether *port,
 			  struct sk_buff *skb,
 			  struct sk_buff_head *list)
 {
 	struct f_ncm	*ncm = func_to_ncm(&port->func);
 	unsigned char	*ntb_ptr = skb->data;
 	__le16		*tmp;
 	unsigned	index, index2;
 	int		ndp_index;
 	unsigned	dg_len, dg_len2;
 	unsigned	ndp_len;
 	unsigned	block_len;
 	struct sk_buff	*skb2;
 	int		ret = -EINVAL;
 	unsigned	ntb_max = le32_to_cpu(ntb_parameters.dwNtbOutMaxSize);
 	unsigned	frame_max;
 	const struct ndp_parser_opts *opts = ncm->parser_opts;
 	unsigned	crc_len = ncm->is_crc ? sizeof(uint32_t) : 0;
 	int		dgram_counter;
 	int		to_process = skb->len;
 	struct f_ncm_opts *ncm_opts;

 	ncm_opts = container_of(port->func.fi, struct f_ncm_opts, func_inst);
 	frame_max = ncm_opts->max_segment_size;

 parse_ntb:
 	tmp = (__le16 *)ntb_ptr;

 	/* dwSignature */
 	if (get_unaligned_le32(tmp) != opts->nth_sign) {
 		INFO(port->func.config->cdev, "Wrong NTH SIGN, skblen %d\n",
 			skb->len);
 		print_hex_dump(KERN_INFO, "HEAD:", DUMP_PREFIX_ADDRESS, 32, 1,
 			       skb->data, 32, false);

 		goto err;
 	}
 	tmp += 2;
 	/* wHeaderLength */
 	if (get_unaligned_le16(tmp++) != opts->nth_size) {
 		INFO(port->func.config->cdev, "Wrong NTB headersize\n");
 		goto err;
 	}
 	tmp++; /* skip wSequence */

 	block_len = get_ncm(&tmp, opts->block_length);
 	/* (d)wBlockLength */
-	if (block_len > ntb_max) {
-		INFO(port->func.config->cdev, "OUT size exceeded\n");
+	if ((block_len < opts->nth_size + opts->ndp_size) || (block_len > ntb_max)) {
+		INFO(port->func.config->cdev, "Bad block length: %#X\n", block_len);
 		goto err;
 	}

 	ndp_index = get_ncm(&tmp, opts->ndp_index);

 	/* Run through all the NDP's in the NTB */
 	do {
 		/*
 		 * NCM 3.2
 		 * dwNdpIndex
 		 */
 		if (((ndp_index % 4) != 0) ||
 				(ndp_index < opts->nth_size) ||
 				(ndp_index > (block_len -
 					      opts->ndp_size))) {
 			INFO(port->func.config->cdev, "Bad index: %#X\n",
 			     ndp_index);
 			goto err;
 		}

 		/*
 		 * walk through NDP
 		 * dwSignature
 		 */
 		tmp = (__le16 *)(ntb_ptr + ndp_index);
 		if (get_unaligned_le32(tmp) != ncm->ndp_sign) {
 			INFO(port->func.config->cdev, "Wrong NDP SIGN\n");
 			goto err;
 		}
 		tmp += 2;

 		ndp_len = get_unaligned_le16(tmp++);
 		/*
 		 * NCM 3.3.1
 		 * wLength
 		 * entry is 2 items
 		 * item size is 16/32 bits, opts->dgram_item_len * 2 bytes
 		 * minimal: struct usb_cdc_ncm_ndpX + normal entry + zero entry
 		 * Each entry is a dgram index and a dgram length.
 		 */
 		if ((ndp_len < opts->ndp_size
 				+ 2 * 2 * (opts->dgram_item_len * 2)) ||
 				(ndp_len % opts->ndplen_align != 0)) {
 			INFO(port->func.config->cdev, "Bad NDP length: %#X\n",
 			     ndp_len);
 			goto err;
 		}
 		tmp += opts->reserved1;
 		/* Check for another NDP (d)wNextNdpIndex */
 		ndp_index = get_ncm(&tmp, opts->next_ndp_index);
 		tmp += opts->reserved2;

 		ndp_len -= opts->ndp_size;
 		index2 = get_ncm(&tmp, opts->dgram_item_len);
 		dg_len2 = get_ncm(&tmp, opts->dgram_item_len);
 		dgram_counter = 0;

 		do {
 			index = index2;
 			/* wDatagramIndex[0] */
 			if ((index < opts->nth_size) ||
 					(index > block_len - opts->dpe_size)) {
 				INFO(port->func.config->cdev,
 				     "Bad index: %#X\n", index);
 				goto err;
 			}

 			dg_len = dg_len2;
 			/*
 			 * wDatagramLength[0]
 			 * ethernet hdr + crc or larger than max frame size
 			 */
 			if ((dg_len < 14 + crc_len) ||
 					(dg_len > frame_max)) {
 				INFO(port->func.config->cdev,
 				     "Bad dgram length: %#X\n", dg_len);
 				goto err;
 			}
 			if (ncm->is_crc) {
 				uint32_t crc, crc2;

 				crc = get_unaligned_le32(ntb_ptr +
 							 index + dg_len -
 							 crc_len);
 				crc2 = ~crc32_le(~0,
 						 ntb_ptr + index,
 						 dg_len - crc_len);
 				if (crc != crc2) {
 					INFO(port->func.config->cdev,
 					     "Bad CRC\n");
 					goto err;
 				}
 			}

 			index2 = get_ncm(&tmp, opts->dgram_item_len);
 			dg_len2 = get_ncm(&tmp, opts->dgram_item_len);

 			/* wDatagramIndex[1] */
 			if (index2 > block_len - opts->dpe_size) {
 				INFO(port->func.config->cdev,
 				     "Bad index: %#X\n", index2);
 				goto err;
 			}

 			/*
 			 * Copy the data into a new skb.
 			 * This ensures the truesize is correct
 			 */
 			skb2 = netdev_alloc_skb_ip_align(ncm->netdev,
 							 dg_len - crc_len);
 			if (skb2 == NULL)
 				goto err;
 			skb_put_data(skb2, ntb_ptr + index,
 				     dg_len - crc_len);

 			skb_queue_tail(list, skb2);

 			ndp_len -= 2 * (opts->dgram_item_len * 2);

 			dgram_counter++;
 			if (index2 == 0 || dg_len2 == 0)
 				break;
 		} while (ndp_len > 2 * (opts->dgram_item_len * 2));
 	} while (ndp_index);

 	VDBG(port->func.config->cdev,
 	     "Parsed NTB with %d frames\n", dgram_counter);

 	to_process -= block_len;

 	/*
 	 * Windows NCM driver avoids USB ZLPs by adding a 1-byte
 	 * zero pad as needed.
 	 */
 	if (to_process == 1 &&
 	    (*(unsigned char *)(ntb_ptr + block_len) == 0x00)) {
 		to_process--;
 	} else if ((to_process > 0) && (block_len != 0)) {
 		ntb_ptr = (unsigned char *)(ntb_ptr + block_len);
 		goto parse_ntb;
 	}

 	dev_consume_skb_any(skb);

 	return 0;
 err:
 	skb_queue_purge(list);
 	dev_kfree_skb_any(skb);
 	return ret;
 }



